def priority(task, state, k=4.0, m=2.5, q=0.5):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    base = tier * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    lateness = task.due - state.now - task.estimated_runtime
    if lateness < 0:
        base *= (1.0 + q * (-lateness) / max(state.mean_est, 1e-6))
    if state.free < 0.2 * state.capacity:
        base *= 1.0 + 1.0 / max(task.estimated_runtime, 1e-6)
    return base

def priority(task, state, k=3.0, m=2.0, alpha=0.5):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    est = max(task.estimated_runtime, 1e-6)
    atc = task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    slacksq = (task.due - state.now - est)
    if slacksq < 0:
        slacksq = slacksq * slacksq
    else:
        slacksq = 0.0
    return tier * (atc + alpha * slacksq / max(state.mean_est, 1e-6))

