import math
def priority(task, state, k=0.5, m=3.0, q_hi=8.0, q_lo=2.0):
    est = max(task.estimated_runtime, 1e-6)
    slack = max(0.0, task.due - est - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    atc = tier * task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    # under load, favor short jobs to clear backlog; light load, favor slack urgency
    load = state.queue_len
    if load >= q_hi:
        return atc / est
    if load <= q_lo:
        return atc * (1.0 + 1.0 / est)
    return atc

import math
def priority(task, state, k=0.5, m=3.0, q_hi=8.0, q_lo=2.0, spt_w=1.0):
    est = max(task.estimated_runtime, 1e-6)
    slack = max(0.0, task.due - est - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    atc = tier * task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    load = state.queue_len
    if load >= q_hi:
        return atc / est
    if load <= q_lo:
        return atc * (1.0 + spt_w / est)
    return atc

