def priority(task, state, k=3.0, m=2.0, q=0.5, gamma=1.0):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    atc = tier * task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    load = state.queue_work / max(state.capacity, 1e-6)
    if load > q:
        return atc * (1.0 + gamma * (state.now - task.release) / max(state.mean_est, 1e-6))
    return atc

import math
def priority(task, state, k=2.0, m=5.0, gamma=1.0, load_thresh=0.5):
    est = max(task.estimated_runtime, 1e-6)
    slack = task.due - est - state.now
    tier = m if task.tenant == 'premium' else 1.0
    base = tier * task.weight / est * math.exp(-max(0.0, slack) / (k * max(state.mean_est, 1e-6)))
    load = state.queue_work / max(state.capacity, 1e-6)
    if slack < 0:
        return 1e6 * tier + base
    if load > load_thresh:
        return base * (1.0 + gamma * (state.now - task.release) / max(state.mean_est, 1e-6))
    return base

