def priority(task, state, m=4.0, g=1.0):
    # Min-slack normalized by runtime, so short urgent jobs dominate;
    # premium tier boosted, extra push once past due.
    slack = task.due - state.now - task.estimated_runtime
    tier = m if task.tenant == 'premium' else 1.0
    score = -slack / max(task.estimated_runtime, 1e-6) * tier
    if slack < 0:
        score += g * (-slack) / max(task.estimated_runtime, 1e-6)
    return score

