def priority(task, state, m=3.0, b=2.0, qthresh=8.0, k=3.0):
    # Switch behavior with queue congestion: when queue is large, prioritize
    # urgency+aging; when small, use tenant-weighted WSJF.
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    tier = m if task.tenant == 'premium' else 1.0
    wsjf = tier * task.weight / est
    if state.queue_len >= qthresh:
        slack = max(0.0, task.due - est - state.now)
        urgency = math.exp(-slack / (k * max(state.mean_est, 1e-6)))
        return wsjf * urgency * (1.0 + b * wait / est)
    return wsjf * (1.0 + 0.5 * b * wait / est)

def priority(task, state, m=3.0, b=1.5, k=3.0, lateness_boost=5.0):
    # Tenant-weighted WSJF with aging, plus a strong boost for already-late
    # requests (slack negative) to reduce late completions.
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    tier = m if task.tenant == 'premium' else 1.0
    slack = task.due - est - state.now
    base = tier * task.weight / est * (1.0 + b * wait / est)
    if slack < 0:
        return base * (lateness_boost + (-slack) / max(state.mean_est, 1e-6))
    return base * math.exp(-slack / (k * max(state.mean_est, 1e-6)))

